mapper.select:
SELECT f.favorite_id, f.user_id, f.article_id, f.create_time, f.deleted_at FROM favorites f WHERE f.user_id = #{userId} AND f.deleted_at IS NULL AND EXISTS ( SELECT 1 FROM articles a WHERE a.article_id = f.article_id AND a.status = 'PUBLISHED' AND a.visibility = 'PUBLIC' AND a.deleted_at IS NULL )
AND ( f.create_time < #{cursorCreateTime} OR (f.create_time = #{cursorCreateTime} AND f.favorite_id < #{cursorFavoriteId}) )
ORDER BY f.create_time DESC, f.favorite_id DESC LIMIT #{limit}
